SELECT CASE WHEN p.stock_qty >= 321 THEN 'high' WHEN p.stock_qty >= 160 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(DISTINCT i.quantity) AS unique_stores, AVG(i.quantity) AS avg_quantity FROM inventory i LEFT JOIN products p ON i.product_id = p.id FULL OUTER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN p.stock_qty >= 321 THEN 'high' WHEN p.stock_qty >= 160 THEN 'mid' ELSE 'low' END ORDER BY avg_quantity DESC;
